import { cleanup, render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { createRef, type FormEvent } from "react";
import { afterEach, describe, expect, it, vi } from "vitest";
import { Button } from "./button";

// Class names of a CSS module are generated by Vite, so pin them for the test.
vi.mock("./button.module.css", () => ({
	default: { button: "button-class" },
}));

describe("Button", () => {
	// Vitest globals are off, so Testing Library can't register this itself.
	afterEach(cleanup);

	it("renders a button with the children", () => {
		render(<Button>content</Button>);

		expect(screen.getByRole("button", { name: "content" })).toBeInstanceOf(
			HTMLButtonElement,
		);
	});

	it("merges the custom class name with the button class", () => {
		render(<Button className="custom" />);

		expect(screen.getByRole("button").className).toBe("button-class custom");
	});

	describe("type", () => {
		it("defaults to button, not submit", () => {
			render(<Button />);

			expect(screen.getByRole("button").getAttribute("type")).toBe("button");
		});

		it("can be overridden", () => {
			render(<Button type="submit" />);

			expect(screen.getByRole("button").getAttribute("type")).toBe("submit");
		});

		it("does not submit a form by default", async () => {
			const user = userEvent.setup();
			// Prevents jsdom's navigation, which it doesn't implement.
			const onSubmit = vi.fn((event: FormEvent) => event.preventDefault());
			render(
				<form onSubmit={onSubmit}>
					<Button />
				</form>,
			);

			await user.click(screen.getByRole("button"));

			expect(onSubmit).not.toHaveBeenCalled();
		});
	});

	it("passes native attributes to the button", () => {
		render(<Button aria-label="Close" disabled />);

		const button = screen.getByRole("button", { name: "Close" });

		expect(button.hasAttribute("disabled")).toBe(true);
	});

	it("passes event handlers to the button", async () => {
		const user = userEvent.setup();
		const onClick = vi.fn();
		render(<Button onClick={onClick} />);

		await user.click(screen.getByRole("button"));

		expect(onClick).toHaveBeenCalledOnce();
	});

	it("forwards the ref to the button", () => {
		const ref = createRef<HTMLButtonElement>();
		render(<Button ref={ref} />);

		expect(ref.current).toBe(screen.getByRole("button"));
	});
});
